from __future__ import annotations

from dataclasses import dataclass
from typing import List, Optional


SYSTEM_PROMPT = (
    "You are PhysicsJudge, a precise video physics evaluator. You will receive a video generated by AI. It may contain physically plausible or implausible phenomena. "
    "First, critically analyze the video content without any preconceptions. Describe what is happening in the video and answer the questions."
    "If there is no related phenomenon occurs, give the answer NA. "
    "Output strict JSON: DON'T ADD ```json``` or any other markdown formatting"
    '{"answer":"yes|no|NA","confidence":float between 0 and 1,"explanation": "brief"}'
)


@dataclass(frozen=True)
class PhysicsQuestion:
    """Represents a binary physics check."""

    qid: str
    dimension: str  # "mechanics", "thermotics", or "material"
    question: str
    success_condition: str


